    15→export function getHttpUriForMxc(
    16→  baseUrl: string,
    17→  mxc?: string,
    18→  width?: number,
    19→  height?: number,
    20→  resizeMethod?: string,
    21→  allowDirectLinks = false,
    22→  allowRedirects?: boolean,
    23→  useAuthentication?: boolean,
    24→): string {
    25→  if (typeof mxc !== "string" || !mxc) {
    26→    return "";
    27→  }
    28→  if (!mxc.startsWith("mxc://")) {
    29→    if (allowDirectLinks) {
    30→      return mxc;
    31→    } else {
    32→      return "";
    33→    }
    34→  }
    35→
    36→  const [serverName, mediaId, ...rest] = mxc.slice(6).split("/");
    37→  if (
    38→    rest.length > 0 ||
    39→    !validateServerName(serverName) ||
    40→    !validateMediaId(mediaId)
    41→  ) {
    42→    return "";
    43→  }
    44→
    45→  if (useAuthentication) {
    46→    allowRedirects = true; // per docs (MSC3916 always expects redirects)
    47→
    48→    // Dev note: MSC3916 removes `allow_redirect` entirely, but
    49→    // for explicitness we set it here. This makes it slightly more obvious to
    50→    // callers, hopefully.
    51→  }
    52→
    53→  let prefix: string;
    54→  const isThumbnailRequest = !!width || !!height || !!resizeMethod;
    55→  const verb = isThumbnailRequest ? "thumbnail" : "download";
    56→  if (useAuthentication) {
    57→    prefix = `/_matrix/client/v1/media/${verb}`;
    58→  } else {
    59→    prefix = `/_matrix/media/v3/${verb}`;
    60→  }
    61→
    62→  const url = new URL(`${prefix}/${serverName}/${mediaId}`, baseUrl);
    63→
    64→  if (width) {
    65→    url.searchParams.set("width", Math.round(width).toString());
    66→  }
    67→  if (height) {
    68→    url.searchParams.set("height", Math.round(height).toString());
    69→  }
    70→  if (resizeMethod) {
    71→    url.searchParams.set("method", resizeMethod);
    72→  }
    73→
    74→  if (typeof allowRedirects === "boolean") {
    75→    // We add this after, so we don't convert everything to a thumbnail request.
    76→    url.searchParams.set("allow_redirect", JSON.stringify(allowRedirects));
    77→  }
    78→
    79→  return url.href;
    80→}
